import os, glob, subprocess, json
import openpyxl, docx

def dump_pdf(p):
    print('=== PDF:', p)
    res = subprocess.run(['pdftotext', '-layout', p, '-'], capture_output=True, text=True)
    print(res.stdout)

def dump_docx(p):
    print('=== DOCX:', p)
    doc = docx.Document(p)
    for para in doc.paragraphs:
        if para.text.strip():
            print(para.text)
    for t in doc.tables:
        print('--- TABLE ---')
        for r in t.rows:
            print([c.text.strip().replace('\n', ' ') for c in r.cells])

def dump_xlsx(p):
    print('=== XLSX:', p)
    wb = openpyxl.load_workbook(p, data_only=True)
    for name in wb.sheetnames:
        print('Sheet:', name)
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(x is not None for x in row):
                print(row)

for p in sorted(glob.glob('project/**/*.*', recursive=True) + glob.glob('15_model/*.*') + glob.glob('templates/*.*')):
    if p.endswith('.pdf'):
        dump_pdf(p)
    elif p.endswith('.docx'):
        dump_docx(p)
    elif p.endswith('.xlsx'):
        dump_xlsx(p)
    elif p.endswith('.txt') or p.endswith('.csv'):
        print('=== TEXT:', p)
        with open(p) as f:
            print(f.read())
"

