import numpy as np

pg, pf, gamma = 63.0, 43.66, 22.19
hb = pf / gamma

def hd_formula(lu):
    return max(0.43 * (max(lu, 20.0) ** (1.0/3.0)) * ((pg + 10.0) ** 0.25) - 1.5, 0.0)

def drift_pw(hd_eff, hc):
    if hd_eff <= hc:
        return hd_eff * gamma, 4.0 * hd_eff
    else:
        return hc * gamma, min(4.0 * (hd_eff ** 2) / hc, 8.0 * hc)

def add_obs_drifts(grid, x0, x1, y0, y1, h):
    hc = h - hb
    lx, ly = x1 - x0, y1 - y0
    # W face at x0 going -x: check both WW and LW at every point x <= x0
    for hd_eff in [0.75 * hd_formula(x0), 1.00 * hd_formula(lx)]:
        p, w = drift_pw(hd_eff, hc)
        for ix in range(40):
            cx0, cx1 = 6.0*ix, 6.0*(ix+1)
            ox0, ox1 = max(cx0, x0 - w), min(cx1, x0)
            if ox1 > ox0:
                s = p * (1.0 - (x0 - ox1) / w)
                for iy in range(30):
                    if min(6.0*(iy+1), y1) > max(6.0*iy, y0):
                        grid[ix, iy] = max(grid[ix, iy], s)
    # E face at x1 going +x
    for hd_eff in [0.75 * hd_formula(240.0 - x1), 1.00 * hd_formula(lx)]:
        p, w = drift_pw(hd_eff, hc)
        for ix in range(40):
            cx0, cx1 = 6.0*ix, 6.0*(ix+1)
            ox0, ox1 = max(cx0, x1), min(cx1, x1 + w)
            if ox1 > ox0:
                s = p * (1.0 - (ox0 - x1) / w)
                for iy in range(30):
                    if min(6.0*(iy+1), y1) > max(6.0*iy, y0):
                        grid[ix, iy] = max(grid[ix, iy], s)
    # S face at y0 going -y
    for hd_eff in [0.75 * hd_formula(y0), 1.00 * hd_formula(ly)]:
        p, w = drift_pw(hd_eff, hc)
        for iy in range(30):
            cy0, cy1 = 6.0*iy, 6.0*(iy+1)
            oy0, oy1 = max(cy0, y0 - w), min(cy1, y0)
            if oy1 > oy0:
                s = p * (1.0 - (y0 - oy1) / w)
