gages = {
    22: {'t': 0.0295, 'wt': 1.6, 'grav': 106.0, 'defl_cap': 96.8, 'Pnov': 298.0, 'rate': 3.05},
    20: {'t': 0.0358, 'wt': 1.9, 'grav': 130.0, 'defl_cap': 119.1, 'Pnov': 362.0, 'rate': 3.48},
    18: {'t': 0.0474, 'wt': 2.5, 'grav': 177.0, 'defl_cap': 163.2, 'Pnov': 479.0, 'rate': 4.42},
}
t20 = 0.0358
Qs_map = {'SCREW-10': 310.0, 'BP': 95.0}
sl_rate = {'SCREW-10': 1.15, 'BP': 0.32}

for g in [22, 20, 18]:
    t = gages[g]['t']
    for n in [4, 5, 7, 9]:
        for sl in ['BP', 'SCREW-10']:
